import React from 'react';
import {
  ActionType,
  Hooks,
  TableInstance,
  TableState,
  actions,
  ensurePluginOrder,
} from 'react-table';

const pluginName = 'usePagination';

// Actions
actions.setPageIndex = 'setPageIndex';
actions.setPageSize = 'setPageSize';

function reducer(state: TableState, action: ActionType) {
  if (action.type === actions.setPageIndex) {
    const { pageIndex } = action;

    return {
      ...state,
      pageIndex,
    };
  }

  if (action.type === actions.setPageSize) {
    const { pageSize } = action;

    return {
      ...state,
      pageSize,
    };
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function useInstance(instance: TableInstance<any>) {
  const {
    rows,
    plugins,
    manualPagination,
    state: { pageSize, pageIndex },
    dispatch,
  } = instance;

  ensurePluginOrder(
    plugins,
    ['useGlobalFilter', 'useFilters', 'useGroupBy', 'useSortBy', 'useExpanded'],
    'usePagination',
  );

  const pageCount =
    pageSize && rows.length > 0 ? Math.ceil(rows.length / pageSize) : 1;

  const page = React.useMemo(() => {
    let page;

    if (manualPagination || pageSize === undefined) {
      page = rows;
    } else {
      const pageStart = pageSize * pageIndex;
      const pageEnd = pageStart + pageSize;

      page = rows.slice(pageStart, pageEnd);
    }

    return page;
  }, [manualPagination, pageIndex, pageSize, rows]);

  const canPreviousPage = pageIndex > 0;
  const canNextPage = pageIndex < pageCount - 1;

  const setPageIndex = React.useCallback(
    (pageIndex?: number) => {
      dispatch({ type: actions.setPageIndex, pageIndex });
    },
    [dispatch],
  );

  const setPageSize = React.useCallback(
    (pageSize?: number) => {
      dispatch({ type: actions.setPageSize, pageSize });
    },
    [dispatch],
  );

  Object.assign(instance, {
    manualPagination,
    pageCount,
    page,
    canPreviousPage,
    canNextPage,
    setPageIndex,
    setPageSize,
  });
}

/** Table hook that enables pagination on tables. */
export function usePagination<D extends Record<string, unknown>>(
  hooks: Hooks<D>,
): void {
  hooks.stateReducers.push(reducer);
  hooks.useInstance.push(useInstance);
}

usePagination.pluginName = pluginName;
